/bin/bash -lc "python - <<'PY'
import json, pathlib, re, subprocess, struct
paths = subprocess.check_output([\"git\", \"ls-files\", \"doc\"], text=True).splitlines()
for p in paths:
    b = pathlib.Path(p).read_bytes()
    ext = pathlib.Path(p).suffix.lower()
    text = \"\"
    if ext in {\".rst\",\".md\",\".txt\",\".py\",\".html\",\".css\",\".json\",\".conf\",\".bat\",\".dot\",\".gitignore\"} or pathlib.Path(p).name in {\"Makefile\",\"matplotlibrc\"}:
        text = b.decode(\"utf-8\", \"replace\")
    lines = text.splitlines()
    title = \"\"
    for i,line in enumerate(lines):
        s=line.strip()
        if not s or s.startswith((\".. _\",\".. include\",\".. image\",\".. toctree\")): continue
        if s.startswith(\"#\"):
            title=s.lstrip(\"#\").strip(); break
        if i+1<len(lines) and lines[i+1].strip() and set(lines[i+1].strip()) <= set(\"=-~"'^*+#") and len(lines[i+1].strip())>=min(3,len(s)):
            title=s; break
        if not title and not s.startswith(("//","/*","*","@","..")):
            title=s[:160]
    paras=[]
    cur=[]
    for line in lines:
        s=line.strip()
        if not s:
            if cur:
                z=" ".join(cur)
                if len(z)>25 and z!=title and not z.startswith((".. ","#","/*")): paras.append(z)
                cur=[]
            continue
        if s.startswith((".. _",".. toctree",".. image",".. include",".. automodule",".. autosummary",".. currentmodule")): continue
        cur.append(s)
    if cur: paras.append(" ".join(cur))
    summary=next((x for x in paras if title not in x[:len(title)+5]), "")
    summary=re.sub(r"'"\\s+\",\" \",summary)[:280]
    norms=[]
    for line in lines:
        s=line.strip()
        if re.search(r\"\\b(must|should|required|do not|never|only|deprecated|shall|需要|必须|不得)\\b\",s,re.I):
            norms.append(re.sub(r\"\\s+\",\" \",s)[:220])
            if len(norms)==3: break
    meta={\"path\":p,\"size\":len(b),\"lines\":len(lines),\"title\":title[:180],\"summary\":summary,\"norms\":norms,\"ext\":ext}
    if b.startswith(b\"\\x89PNG\\r\\n\\x1a\\n\") and len(b)>=24:
        meta[\"image\"]={\"format\":\"PNG\",\"width\":int.from_bytes(b[16:20],\"big\"),\"height\":int.from_bytes(b[20:24],\"big\")}
    elif ext==\".svg\":
        m=re.search(r\"<svg["'^>]*(?:viewBox=['"\\\"'](["'^'"\\\"']+)|width=[\\\"'](["'^'"\\\"']+))\",text,re.I)
        meta[\"image\"]={\"format\":\"SVG\",\"geometry\":m.group(0)[:180] if m else \"\"}
    elif ext==\".pdf\": meta[\"image\"]={\"format\":\"PDF\"}
    elif ext==\".ico\": meta[\"image\"]={\"format\":\"ICO\"}
    print(json.dumps(meta,ensure_ascii=False))
PY"

