/bin/bash -lc "python - <<'PY'
import json,pathlib,re,subprocess
asset={'.png','.pdf','.svg','.eps','.ttf','.afm','.pfb','.jpg','.gif','.tif','.npz','.npy','.gz','.ico'}
for p in subprocess.check_output(['git','ls-files'],text=True).splitlines():
 q=pathlib.Path(p); ext=q.suffix.lower()
 if ext in {'.py','.pyi'} or ext in asset or p.startswith('doc/'): continue
 b=q.read_bytes()
 if b'\\0' in b[:8192]: continue
 t=b.decode('utf-8','replace'); ls=t.splitlines()
 comments=[]
 for x in ls:
  s=x.strip()
  if s.startswith(('#','//','/*','*',';')) and len(s)>3:
   z=re.sub(r'"'^(#|//|/'"\\*+|\\*+|;+)[ "'!]*'"','',s).strip(' */')
   if z and not z.startswith(('include','define','pragma')): comments.append(z)
  if len(comments)>=8:break
 syms=[]
 pats=[r'"'^(?:class|struct)'"\\s+([A-Za-z_]\\w*)',r'"'^(?:[A-Za-z_]'"\\w*[\\w:<>,*&\\s]+)\\s+([A-Za-z_]\\w*)\\s*\\(["'^;]*'"\\)\\s*(?:\\{|"'$)'"',r'"'^(?:function'"\\s+)?([A-Za-z_"'$]'"\\w*)\\s*\\(["'^)]*'"\\)\\s*\\{']
 for x in ls:
  s=x.strip()
  for pat in pats:
   m=re.match(pat,s)
   if m and m.group(1) not in {'if','for','while','switch','catch'}:syms.append(m.group(1));break
  if len(syms)>=30:break
 inc=[]
 for x in ls:
  m=re.match(r'\\s*#\\s*include\\s*[<\"](["'^>"]+)'"',x)
  if m:inc.append(m.group(1))
 keys=[]
 for x in ls:
  m=re.match(r'\\s*([A-Za-z_][\\w.-]*)\\s*[:=]',x)
  if m:keys.append(m.group(1))
 print(json.dumps({'path':p,'size':len(b),'lines':len(ls),'comments':comments,'symbols':list(dict.fromkeys(syms)),'includes':list(dict.fromkeys(inc))[:20],'keys':list(dict.fromkeys(keys))[:30],'first':next((x.strip() for x in ls if x.strip()),'')[:180]},ensure_ascii=False,separators=(',',':')))
PY"

