/bin/bash -lc "python - <<'PY'
import json,pathlib,re,subprocess,struct,zipfile,io
asset={'.png','.pdf','.svg','.eps','.ttf','.afm','.pfb','.jpg','.gif','.tif','.npz','.npy','.gz','.ico'}
for p in subprocess.check_output(['git','ls-files'],text=True).splitlines():
 q=pathlib.Path(p); ext=q.suffix.lower()
 if ext not in asset: continue
 b=q.read_bytes(); m={'path':p,'size':len(b),'ext':ext}
 if ext=='.png' and b.startswith(b'\\x89PNG') and len(b)>=24:m.update(width=int.from_bytes(b[16:20],'big'),height=int.from_bytes(b[20:24],'big'),format='PNG')
 elif ext=='.gif' and len(b)>=10:m.update(width=int.from_bytes(b[6:8],'little'),height=int.from_bytes(b[8:10],'little'),format='GIF')
 elif ext in {'.jpg','.tif','.ico'}:m['format']=ext[1:].upper()
 elif ext=='.svg':
  t=b.decode('utf-8','replace'); tag=re.search(r'<svg\\b["'^>]*>'"',t,re.I|re.S)
  m['format']='SVG';m['geometry']=re.sub(r'\\s+',' ',tag.group(0))[:300] if tag else ''
  txt=[re.sub(r'<["'^>]+>'"','',x).strip() for x in re.findall(r'<text\\b.*?</text>',t,re.I|re.S)]
